#!/bin/bash
#
# Runs clang-tidy on one translation unit as a build step; the steps are
# generated by script/gen-clang-tidy-ninja.py. Invoked as
#
#   run-clang-tidy-action.sh <clang++|clang-cl> <compile flags...> -c <source> -o <output>
#
# i.e. an ordinary compile command with this script in front, which is what
# lets siso include-scan, cache and remotely execute the step like a compile.
#
# Fails if clang-tidy reports anything, so only clean runs get cached. On
# success writes <output> (an empty stamp) plus the step's header dependencies:
# a depfile <output>.d for clang++, /showIncludes output for clang-cl.

set -euo pipefail

clang=$1
shift

# A macOS host's toolchain can't run on the (Linux) RBE workers. There,
# clang_remote_wrapper has run before us and staged a Linux clang and
# clang-tidy under Release+Asserts_linux; see build/siso/main.star.
if ! "$clang" --version >/dev/null 2>&1; then
  clang=${clang/Release+Asserts/Release+Asserts_linux}
fi
clang_tidy=$(dirname "$clang")/clang-tidy

flags=()
while [[ $# -gt 0 ]]; do
  case $1 in
    -c) source=$2; shift ;;
    -o) output=$2; shift ;;
    *) flags+=("$1") ;;
  esac
  shift
done

mkdir -p "$(dirname "$output")"

if [[ $(basename "$clang") == clang-cl* ]]; then
  "$clang_tidy" --quiet --header-filter= --warnings-as-errors='*' \
      --extra-arg-before=--driver-mode=cl --extra-arg=-Wno-unused-command-line-argument \
      "$source" -- "${flags[@]}"
  "$clang" "${flags[@]}" /showIncludes:user /E "$source" >/dev/null
else
  "$clang_tidy" --quiet --header-filter= --warnings-as-errors='*' "$source" -- "${flags[@]}"
  "$clang" "${flags[@]}" -w -M -MF "$output.d" -MT "$output" "$source"
fi

touch "$output"
